import sys
from itertools import combinations

MOD = 998244353

def is_sorted(arr):
    return all(arr[i] <= arr[i + 1] for i in range(len(arr) - 1))

def count_good_permutations(n, pairs):
    total_permutations = pow(n, n, MOD)

    # Count permutations where the first elements are sorted
    first_elements = [pair[0] for pair in pairs]
    sorted_first_count = 0
    for i in range(1, n + 1):
        for comb in combinations(range(n), i):
            if is_sorted([first_elements[j] for j in comb]):
                sorted_first_count += pow(n - i, n - i, MOD)
                sorted_first_count %= MOD

    # Count permutations where the second elements are sorted
    second_elements = [pair[1] for pair in pairs]
    sorted_second_count = 0
    for i in range(1, n + 1):
        for comb in combinations(range(n), i):
            if is_sorted([second_elements[j] for j in comb]):
                sorted_second_count += pow(n - i, n - i, MOD)
                sorted_second_count %= MOD

    # Count permutations where both first and second elements are sorted
    both_sorted_count = 0
    for i in range(1, n + 1):
        for comb in combinations(range(n), i):
            if is_sorted([first_elements[j] for j in comb]) and is_sorted([second_elements[j] for j in comb]):
                both_sorted_count += pow(n - i, n - i, MOD)
                both_sorted_count %= MOD

    # Use inclusion-exclusion principle
    bad_permutations = (sorted_first_count + sorted_second_count - both_sorted_count) % MOD
    good_permutations = (total_permutations - bad_permutations) % MOD

    return good_permutations

def main():
    import sys
