    n = int(data[0])
    pairs = []
    for i in range(n):
        a = int(data[2 * i + 1])
        b = int(data[2 * i + 2])
        pairs.append((a, b))

    result = count_good_permutations(n, pairs)
    print(result)

if __name__ == "__main__":
    main()
